//! Command line parsing.  The observable surface (option names, error wording,
//! exit codes) mirrors what a `clap`-based front end produces, but the parser
//! itself is a small table driven implementation.

use std::collections::HashMap;
use std::fmt::Write as _;

/// How many values an option consumes.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Arity {
    Flag,
    Value,
}

pub struct OptSpec {
    pub name: &'static str,
    pub long: &'static str,
    pub aliases: &'static [&'static str],
    pub short: Option<char>,
    pub arity: Arity,
    /// Placeholder shown in diagnostics, e.g. `<when>`.
    pub value_name: &'static str,
    /// Non-empty when the option is restricted to a fixed set of values.
    pub possible: &'static [&'static str],
}

const fn flag(name: &'static str, long: &'static str, short: Option<char>) -> OptSpec {
    OptSpec {
        name,
        long,
        aliases: &[],
        short,
        arity: Arity::Flag,
        value_name: "",
        possible: &[],
    }
}

const fn val(
    name: &'static str,
    long: &'static str,
    short: Option<char>,
    value_name: &'static str,
    possible: &'static [&'static str],
) -> OptSpec {
    OptSpec {
        name,
        long,
        aliases: &[],
        short,
        arity: Arity::Value,
        value_name,
        possible,
    }
}

