/// A parse failure that should be reported the way clap reports it (exit 2).
pub struct UsageError(pub String);

pub struct Matches {
    values: HashMap<&'static str, Vec<String>>,
    pub free: Vec<String>,
    pub subcommand: Option<String>,
}

impl Matches {
    fn new() -> Self {
        Matches {
            values: HashMap::new(),
            free: Vec::new(),
            subcommand: None,
        }
    }

    pub fn present(&self, name: &str) -> bool {
        self.values.contains_key(name)
    }

    pub fn count(&self, name: &str) -> usize {
        self.values.get(name).map(|v| v.len()).unwrap_or(0)
    }

    pub fn value(&self, name: &str) -> Option<&str> {
        self.values.get(name).and_then(|v| v.last()).map(|s| s.as_str())
    }

    pub fn values(&self, name: &str) -> &[String] {
        const EMPTY: &[String] = &[];
        self.values.get(name).map(|v| v.as_slice()).unwrap_or(EMPTY)
    }

    fn push(&mut self, name: &'static str, v: String) {
        self.values.entry(name).or_default().push(v);
    }

    /// Merge lower priority values (config file / env) underneath the ones that
    /// were given on the command line.
    pub fn merge_under(&mut self, mut other: Matches) {
        for (k, mut v) in other.values.drain() {
            match self.values.get_mut(k) {
                Some(existing) => {
                    v.append(existing);
                    *existing = v;
                }
                None => {
                    self.values.insert(k, v);
                }
            }
        }
        let mut free = other.free;
        free.append(&mut self.free);
        self.free = free;
    }
}

fn usage_main(bin: &str) -> String {
    format!("Usage: {bin} [OPTIONS] [FILE]...\n       {bin} <COMMAND>\n")
}

fn find_long<'a>(specs: &'a [OptSpec], name: &str) -> Option<&'a OptSpec> {
    specs
        .iter()
        .find(|s| s.long == name || s.aliases.iter().any(|a| *a == name))
}

fn find_short<'a>(specs: &'a [OptSpec], c: char) -> Option<&'a OptSpec> {
    specs.iter().find(|s| s.short == Some(c))
}

/// Jaro-Winkler similarity, used for the "a similar argument exists" hint.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let window = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let lo = i.saturating_sub(window);
        let hi = (i + window + 1).min(b.len());
        for j in lo..hi {
            if !b_match[j] && b[j] == *ca {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[k] {
                k += 1;
            }
            if a[i] != b[k] {
                transpositions += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - transpositions as f64 / 2.0) / m) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j <= 0.7 {
        return j;
    }
    let prefix = a
        .chars()
        .zip(b.chars())
        .take(4)
        .take_while(|(x, y)| x == y)
        .count() as f64;
    j + 0.1 * prefix * (1.0 - j)
}

fn suggest(specs: &[OptSpec], name: &str) -> Option<&'static str> {
    let mut best: Option<(f64, &'static str)> = None;
    for s in specs {
        for cand in std::iter::once(s.long).chain(s.aliases.iter().copied()) {
            let score = jaro_winkler(name, cand);
            if score > 0.7 && best.map(|(b, _)| score > b).unwrap_or(true) {
                best = Some((score, cand));
            }
        }
    }
    best.map(|(_, n)| n)
}

fn spec_usage(bin: &str, spec: &OptSpec) -> String {
    if spec.arity == Arity::Value {
        format!("Usage: {} --{} {} [FILE]...\n", bin, spec.long, spec.value_name)
    } else {
        format!("Usage: {} --{} [FILE]...\n", bin, spec.long)
    }
}

fn unexpected(bin: &str, shown: &str, specs: &[OptSpec], top_level: bool) -> UsageError {
    let mut msg = String::new();
    let _ = writeln!(msg, "error: unexpected argument '{shown}' found");
    let stripped = shown.trim_start_matches('-');
    let hint = if shown.starts_with("--") {
        suggest(specs, stripped)
    } else {
        None
    };
    match hint {
        Some(alt) => {
            let _ = write!(msg, "\n  tip: a similar argument exists: '--{alt}'\n\n");
            let spec = find_long(specs, alt).unwrap();
            msg.push_str(&spec_usage(bin, spec));
        }
        None => {
            if top_level {
                let _ = write!(
                    msg,
                    "\n  tip: to pass '{shown}' as a value, use '-- {shown}'\n\n"
                );
                msg.push_str(&usage_main(bin));
            } else {
                let _ = write!(msg, "\nUsage: {bin} cache [OPTIONS]\n\n");
                msg.push_str("For more information, try '--help'.\n");
            }
        }
    }
    UsageError(msg)
}

fn missing_value(spec: &OptSpec) -> UsageError {
    let mut msg = format!(
        "error: a value is required for '--{} {}' but none was supplied\n",
        spec.long, spec.value_name
    );
    if !spec.possible.is_empty() {
        let _ = writeln!(msg, "  [possible values: {}]", spec.possible.join(", "));
    }
    UsageError(msg)
}

pub fn invalid_value(spec_long: &str, value_name: &str, value: &str, detail: Option<&str>) -> UsageError {
    let mut msg = format!("error: invalid value '{value}' for '--{spec_long} {value_name}'");
    match detail {
        Some(d) => {
            let _ = writeln!(msg, ": {d}");
        }
        None => msg.push('\n'),
    }
    UsageError(msg)
}

fn bad_possible(spec: &OptSpec, value: &str) -> UsageError {
    let mut msg = format!(
        "error: invalid value '{}' for '--{} {}'\n",
        value, spec.long, spec.value_name
    );
    let _ = writeln!(msg, "  [possible values: {}]", spec.possible.join(", "));
    UsageError(msg)
}

/// Parse `args` (without the program name).  `allow_subcommand` and
/// `allow_free` control the top-level versus `cache` grammar.
pub fn parse(
    bin: &str,
    specs: &'static [OptSpec],
    args: &[String],
    top_level: bool,
) -> Result<Matches, UsageError> {
    let mut m = Matches::new();
    let mut i = 0usize;
    let mut only_free = false;
    while i < args.len() {
        let arg = args[i].clone();
        i += 1;
        if only_free {
            m.free.push(arg);
            continue;
        }
        if arg == "--" {
            only_free = true;
            continue;
        }
        if arg.starts_with("--") {
            let body = &arg[2..];
            let (name, inline) = match body.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (body, None),
            };
            let spec = match find_long(specs, name) {
                Some(s) => s,
                None => {
                    return Err(unexpected(bin, &format!("--{name}"), specs, top_level));
                }
            };
            match spec.arity {
                Arity::Flag => {
                    m.push(spec.name, String::new());
                }
                Arity::Value => {
                    let v = match inline {
                        Some(v) => v,
                        None => match args.get(i) {
                            Some(v) => {
                                i += 1;
                                v.clone()
                            }
                            None => return Err(missing_value(spec)),
                        },
                    };
                    if !spec.possible.is_empty() && !spec.possible.contains(&v.as_str()) {
                        return Err(bad_possible(spec, &v));
                    }
                    m.push(spec.name, v);
                }
            }
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                let spec = match find_short(specs, c) {
                    Some(s) => s,
                    None => {
                        return Err(unexpected(bin, &format!("-{c}"), specs, top_level));
                    }
                };
                match spec.arity {
                    Arity::Flag => m.push(spec.name, String::new()),
                    Arity::Value => {
                        let rest: String = chars[ci..].iter().collect();
                        let v = if !rest.is_empty() {
                            ci = chars.len();
                            rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest)
                        } else {
                            match args.get(i) {
                                Some(v) => {
                                    i += 1;
                                    v.clone()
                                }
                                None => return Err(missing_value(spec)),
                            }
                        };
                        if !spec.possible.is_empty() && !spec.possible.contains(&v.as_str()) {
                            return Err(bad_possible(spec, &v));
                        }
                        m.push(spec.name, v);
                    }
                }
            }
            continue;
        }
        if top_level && m.subcommand.is_none() && m.free.is_empty() && arg == "cache" {
            m.subcommand = Some(arg);
            // Everything that follows belongs to the subcommand.
            let rest: Vec<String> = args[i..].to_vec();
            m.free = rest;
            return Ok(m);
        }
        m.free.push(arg);
    }
    Ok(m)
}

/// Split a config-file / `BAT_OPTS` style string into arguments, honouring
/// single and double quotes.
pub fn split_args(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut has = false;
    let mut quote: Option<char> = None;
    for c in text.chars() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else {
                    cur.push(c);
                }
            }
            None => {
                if c == '\'' || c == '"' {
                    quote = Some(c);
                    has = true;
                } else if c.is_whitespace() {
                    if has || !cur.is_empty() {
                        out.push(std::mem::take(&mut cur));
                        has = false;
                    }
                } else {
                    cur.push(c);
                }
            }
        }
    }
    if has || !cur.is_empty() {
        out.push(cur);
    }
    out
}
